def list_all_files(directory, max_depth=3):
    """List all files in directory up to max_depth"""
    results = []
    for root, dirs, files in os.walk(directory):
        depth = root.count(os.sep) - directory.count(os.sep)
        if depth >= max_depth:
            continue
        for f in files:
            full_path = os.path.join(root, f)
            rel_path = full_path.replace(directory + os.sep, "")
